_VOWELS = frozenset("aeiou")


def translate(text):
    """Translate each word in *text* to Pig Latin."""
    return " ".join(_translate_word(word) for word in text.split())


def _translate_word(word):
    if _is_rule_one_word(word):
        return word + "ay"

    split_at = _leading_cluster_length(word)
    return word[split_at:] + word[:split_at] + "ay"


def _is_rule_one_word(word):
    return word[0] in _VOWELS or word.startswith(("xr", "yt"))


def _leading_cluster_length(word):
    split_at = 0
    word_length = len(word)

    while split_at < word_length:
        character = word[split_at]

        if character in _VOWELS:
            break
        if character == "y" and split_at > 0:
            break
        if (
            character == "q"
            and split_at + 1 < word_length
            and word[split_at + 1] == "u"
        ):
            split_at += 2
            break

        split_at += 1

    return split_at

